'use strict';
const $=s=>document.querySelector(s);
const safe=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=value=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(value);
let active='overview',requests=[],docs=[],toastTimer,modalOpener;
function toast(message){const box=$('#toast');box.textContent=message;box.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>{box.style.display='none'},4500)}
function openModal(html,kicker='CRÉDIT PME'){modalOpener=document.activeElement;$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=html;const title=$('#modal-content h2');if(title)title.id='dialog-title';$('#modal').showModal();window.CreditExperience?.enhance($('#modal-content'))}
function closeModal(){$('#modal').close();modalOpener?.focus?.()}
$('#close-modal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
$('#privacy').onclick=()=>openModal('<h2>Vos données, votre espace.</h2><p>Les brouillons explicitement enregistrés et les originaux reçus sont conservés dans le stockage privé du serveur. Un fichier seulement sélectionné sur cette page doit être importé avant de pouvoir être repris après rechargement.</p><p>Seules vos préférences d’affichage sont conservées sur cet appareil. Aucun document, revenu ou identifiant personnel n’est enregistré dans le stockage du navigateur.</p><p>Le traitement et la transmission des dossiers nécessitent un compte et un service métier authentifiés.</p>','CONFIDENTIALITÉ');
function table(rows=requests){return `<div class="panel table-scroll"><table><thead><tr><th scope="col">PROJET</th><th scope="col">MONTANT · FCFA</th><th scope="col">MISE À JOUR</th><th scope="col">STATUT</th><th scope="col"><span class="sr-only">Ouvrir</span></th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td><div class="request-name"><span class="request-icon" aria-hidden="true">↗</span><span><strong>${safe(r.name)}</strong><small>${safe(r.type)}</small></span></div></td><td class="money">${money(r.amount)}</td><td>${safe(r.date)}</td><td><span class="badge grey">${safe(r.status)}</span></td><td><button class="row-link" data-detail="${safe(r.id)}" aria-label="Ouvrir ${safe(r.name)}">↗</button></td></tr>`).join(''):'<tr><td colspan="5"><div class="empty-state"><span aria-hidden="true">↗</span><h3>Votre prochain projet commence ici.</h3><p>Retrouvez vos demandes au même endroit.</p><a href="#choix" class="outline">Créer une demande →</a></div></td></tr>'}</tbody></table></div>`}
function overview(){return `<div class="stories"><article class="story story-business photo-surface"><video class="home-video" data-src="assets/videos/african-card-payment.mp4" data-title="Utilisation d’une carte bancaire sur un ordinateur" poster="assets/videos/african-card-payment-poster.jpg" muted loop playsinline preload="none" aria-hidden="true" tabindex="-1"></video><div class="story-top"><span class="glass-label">Entreprises & PME</span><button type="button" class="home-video-toggle">▶ Lire</button></div><div class="story-copy"><h2>Votre activité.<br>En plus grand.</h2><a class="white-pill" href="#choix">Préparer mon financement ↗</a></div><a class="floating-note" href="#demande"><span class="note-icon">↗</span><span><strong>Un dossier qui vous ressemble.</strong><small>Avancez à votre rythme.</small></span><span>→</span></a></article><article class="story story-personal photo-surface"><video class="home-video" data-src="assets/videos/african-market.mp4" data-title="Opération sur un distributeur bancaire" poster="assets/videos/african-market-poster.jpg" muted loop playsinline preload="none" aria-hidden="true" tabindex="-1"></video><div class="story-top"><span class="glass-label">Particuliers</span><button type="button" class="home-video-toggle">▶ Lire</button></div><div class="story-copy"><h2>La prochaine étape<br>commence ici.</h2><button class="white-pill" id="personal-start">Préparer ma demande ↗</button></div><div class="floating-note"><span class="note-icon lavender">✓</span><span><strong>Simple, du début à la suite.</strong><small>Demande. Documents. Suivi.</small></span></div></article></div><div class="story-pagination" aria-hidden="true"><i></i><i></i></div>${window.CreditBudget?.shell() || ''}<div class="progress-banner"></div><div class="stats"><article class="stat"><div class="stat-top"><span>Demandes en cours</span></div><div class="stat-value">${requests.length}</div><div class="stat-note">Vos projets</div></article><article class="stat"></article><article class="stat"></article></div><div class="section-head"><h2>Vos demandes</h2><a class="text-button" href="#requests">Tout voir →</a></div>${table()}`}
function bindView(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));const search=$('#search');if(search){const filter=()=>{const text=search.value.toLocaleLowerCase('fr');const type=$('#filter-type').value;$('#request-table').innerHTML=table(requests.filter(r=>r.name.toLocaleLowerCase('fr').includes(text)&&(!type||r.type===type)));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail))};search.oninput=filter;$('#filter-type').onchange=filter}}
function detail(){location.hash='demande'}
function renderLegacy(){active=location.hash.slice(1)||'overview';const all=active==='requests';$('#page-title').textContent=all?'Vos projets, au même endroit.':'Vos projets. La vie devant.';$('#page-subtitle').textContent=all?'Suivez chaque demande.':'Votre prochain financement commence ici.';$('#view').innerHTML=all?`<div class="toolbar"><input type="search" id="search" placeholder="Rechercher un projet" aria-label="Rechercher une demande"><select id="filter-type" aria-label="Type de demandeur"><option value="">Tous les profils</option><option>Entreprise</option><option>Particulier</option></select></div><div id="request-table">${table()}</div>`:overview();$('#nav-count').textContent=requests.length;document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===active));bindView()}
function render(){window.renderApp?.()}
window.addEventListener('hashchange',render);
